#include <cuda.h>
#include <cuda_runtime.h>

__global__ void elementwise_add(float* left, float* right, float* output, int length) {
    // Define block and thread indices
    int block_id = blockIdx.x;
    int thread_id = threadIdx.x;

    // Calculate global index
    int global_index = block_id * blockDim.x + thread_id;

    // Check if the global index is within bounds
    if (global_index < length) {
        output[global_index] = left[global_index] + right[global_index];
    }
}
